SELECT percentile_cont(0.9) within GROUP (ORDER BY instability_score) AS percentile_90, COUNT(*) FILTER (WHERE instability_score >= percentile_90) AS high_scores, SUM(CASE WHEN gender = 'M' AND age BETWEEN 53 AND 63 AND anchor_year_group = 'Post-arrest' THEN 1 ELSE 0 END) FILTER (WHERE instability_score >= percentile_90) AS male_high_scores, AVG(icu_stay_duration) FILTER (WHERE instability_score >= percentile_90) AS avg_icu_stay_duration, SUM(CASE WHEN gender = 'F' AND age BETWEEN 53 AND 63 AND anchor_year_group = 'Post-arrest' THEN 1 ELSE 0 END) FILTER (WHERE instability_score >= percentile_90) AS female_high_scores, SUM(CASE WHEN gender = 'F' AND age BETWEEN 53 AND 63 AND anchor_year_group = 'Post-arrest' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) AS female_to_total_ratio FROM total_data WHERE instability_score >= percentile_90;